import json


def normalize_expense(expense):
    normalized_expense = {
        "vendor": expense.get("vendor"),
        "date": expense.get("date"),
        "total": expense.get("total"),
        "line_items": [
            {
                "description": item.get("description"),
                "quantity": item.get("quantity"),
                "amount": item.get("amount")
            }
            for item in expense.get("line_items", [])
        ]
    }
    return json.dumps(normalized_expense, indent=2)

import json


def validate_document_fields(document):
    required_fields = ["vendor", "date", "total"]
    for field in required_fields:
        if field not in document:
            return False
    if "line_items" not in document or not document["line_items"]:
        return False
    for item in document["line_items"]:
        if "description" not in item or "quantity" not in item or "amount" not in item:
            return False
    return True

import os
import boto3


def get_textract_client(region=None):
    region = region or os.getenv("AWS_DEFAULT_REGION", "us-west-2")
    return boto3.client("textract", region_name=region)

def normalize_expense_response(response):
    normalized_expense = {
        "vendor": response["vendor"],
        "date": response["date"],
        "total": response["total"],
        "line_items": [
            {
                "description": item["description"],
                "quantity": item["quantity"],
                "amount": item["amount"]
            }
            for item in response["line_items"]
        ]
    }
    return normalized_expense

import json


def summarize_invoice_fields(invoice):
    summary = {
        "vendor": invoice["vendor"],
        "date": invoice["date"],
        "total": invoice["total"],
        "line_items_count": len(invoice["line_items"])
    }
    return json.dumps(summary, indent=2)
